 $source=new class implements BrTopPermissionSourceInterface{public function memberGroupId():?string{return 'br-members';}public function chairGroupId():?string{return 'br-chair';}public function deputyGroupId():?string{return 'br-deputy';}};$provider=new BrTopPermissionProvider($source);$result=$provider->collect();$rules=$result->rules;$member=[];$admin=[];$chair=[];foreach($rules as $rule){if($rule->condition->operator==='group'&&$rule->condition->groupId==='br-members')$member[$rule->permission]=$rule;if($rule->condition->operator==='group'&&$rule->condition->groupId==='br-chair')$chair[$rule->permission]=$rule;if($rule->condition->operator==='all')$admin[$rule->permission]=$rule;}
